def transform(grid):
    """Fill horizontal gaps between matching marker cells with color 2."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        markers = [c for c, v in enumerate(row) if v == 6]
        for left, right in zip(markers, markers[1:]):
            for c in range(left + 1, right):
                out[r][c] = 2
    return out

